/* FDT parser against a DTB generated by tools/mkdtb.py --preset rpi5-like
 * (path passed as argv[1]). */
#include <stdint.h>
#include "test.h"
#include "fdt.h"

static void *load(const char *path, long *len)
{
    FILE *f = fopen(path, "rb");
    void *buf;
    if (!f)
        return NULL;
    fseek(f, 0, SEEK_END);
    *len = ftell(f);
    fseek(f, 0, SEEK_SET);
    buf = malloc((size_t)*len + 8);
    if (fread(buf, 1, (size_t)*len, f) != (size_t)*len) {
        fclose(f);
        free(buf);
        return NULL;
    }
    fclose(f);
    return buf;
}

static const void *fdt;

static void test_header(void)
{
    CHECK(fdt_check(fdt) == 0);
    CHECK(fdt_check(NULL) == -1);
    {
        unsigned char bad[64] = { 0 };
        CHECK(fdt_check(bad) == -1);
    }
}

static void test_paths(void)
{
    int mem = fdt_path_offset(fdt, "/memory");
    int soc = fdt_path_offset(fdt, "/soc");
    int uart = fdt_path_offset(fdt, "/soc@107c000000/serial@7d001000");
    CHECK(fdt_path_offset(fdt, "/") == 0);
    CHECK(mem > 0);
    CHECK_STR(fdt_node_name(fdt, mem), "memory@0");
    CHECK(soc > 0 && uart > 0);
    CHECK(fdt_parent(fdt, uart) == soc);
    CHECK(fdt_parent(fdt, soc) == 0);
    CHECK(fdt_path_offset(fdt, "/nope") < 0);
    CHECK(fdt_path_offset(fdt, "/soc/serial") > 0); /* unit-address optional */
    CHECK(fdt_path_offset(fdt, "relative") < 0);
}

static void test_memory_reg(void)
{
    uint64_t a = 1, s = 0;
    int mem = fdt_path_offset(fdt, "/memory");
    CHECK(fdt_address_cells(fdt, 0) == 2);
    CHECK(fdt_size_cells(fdt, 0) == 1);
    CHECK(fdt_reg(fdt, mem, 0, &a, &s) == 0);
    CHECK(a == 0 && s == 0x3f800000ULL);
    CHECK(fdt_reg(fdt, mem, 1, &a, &s) == -1); /* only one entry */
}

static void test_ranges_translation(void)
{
    uint64_t a = 0, s = 0;
    int uart = fdt_path_offset(fdt, "/soc/serial@7d001000");
    int gic = fdt_node_by_compatible(fdt, -1, "arm,gic-400");
    CHECK(fdt_reg(fdt, uart, 0, &a, &s) == 0);
    CHECK(a == 0x107d001000ULL); /* 0x7d001000 through soc ranges */
    CHECK(s == 0x200);
    CHECK(gic > 0);
    CHECK(fdt_reg(fdt, gic, 0, &a, &s) == 0 && a == 0x107fff9000ULL && s == 0x1000);
    CHECK(fdt_reg(fdt, gic, 1, &a, &s) == 0 && a == 0x107fffa000ULL && s == 0x2000);
}

static void test_untranslatable(void)
{
    /* The RP1 UART sits under a bus with no "ranges": not CPU-addressable. */
    uint64_t a;
    int rp1 = fdt_path_offset(fdt, "/axi/pcie@120000/rp1/serial@30000");
    CHECK(rp1 > 0);
    CHECK(fdt_reg(fdt, rp1, 0, &a, 0) == -1);
}

static void test_compatible_and_status(void)
{
    int n = fdt_node_by_compatible(fdt, -1, "arm,pl011"), count = 0, enabled = 0;
    while (n >= 0) {
        count++;
        enabled += fdt_is_enabled(fdt, n);
        n = fdt_node_by_compatible(fdt, n, "arm,pl011");
    }
    CHECK(count == 3);   /* debug UART, disabled UART, RP1 UART */
    CHECK(enabled == 2); /* status absent counts as enabled */
    CHECK(fdt_node_by_compatible(fdt, -1, "arm,primecell") > 0); /* 2nd string */
    CHECK(fdt_node_by_compatible(fdt, -1, "arm,pl01") < 0);      /* no prefix match */
}

static void test_props_aliases(void)
{
    int len, chosen = fdt_path_offset(fdt, "/chosen"), n, plen = 0;
    const char *sp = fdt_getprop(fdt, chosen, "stdout-path", &len);
    const char *m;
    uint64_t a;
    CHECK(sp != NULL);
    CHECK_STR(sp, "serial10:115200n8");
    while (sp[plen] && sp[plen] != ':')
        plen++;
    n = fdt_resolve(fdt, sp, plen);
    CHECK(n == fdt_path_offset(fdt, "/soc/serial@7d001000"));
    CHECK(fdt_reg(fdt, n, 0, &a, 0) == 0 && a == 0x107d001000ULL);
    CHECK(fdt_resolve(fdt, "serial99", 8) < 0);
    m = fdt_getprop(fdt, fdt_path_offset(fdt, "/psci"), "method", &len);
    CHECK(m && strcmp(m, "smc") == 0 && len == 4);
    CHECK(fdt_getprop(fdt, 0, "missing", &len) == NULL);
    CHECK(fdt_prop_u32(fdt, 0, "#address-cells", 0) == 2);
    CHECK(fdt_prop_u32(fdt, 0, "missing", 77) == 77);
}

static void test_timer_irq(void)
{
    int len, t = fdt_node_by_compatible(fdt, -1, "arm,armv8-timer");
    const unsigned char *p = fdt_getprop(fdt, t, "interrupts", &len);
    CHECK(p && len == 48);
    CHECK(p && p[19] == 14); /* entry 1 (NS EL1 phys) = PPI 14 -> INTID 30 */
}

static void test_memreserve(void)
{
    uint64_t a = 9, s = 9;
    CHECK(fdt_memreserve(fdt, 0, &a, &s) == 0 && a == 0 && s == 0x1000);
    CHECK(fdt_memreserve(fdt, 1, &a, &s) == -1);
}

int main(int argc, char **argv)
{
    long len = 0;
    void *buf;
    if (argc < 2) {
        fprintf(stderr, "usage: test_fdt <rpi5-like.dtb>\n");
        return 2;
    }
    buf = load(argv[1], &len);
    if (!buf) {
        fprintf(stderr, "cannot read %s\n", argv[1]);
        return 2;
    }
    fdt = buf;
    CHECK(fdt_totalsize(fdt) == (uint32_t)len);
    RUN(test_header);
    RUN(test_paths);
    RUN(test_memory_reg);
    RUN(test_ranges_translation);
    RUN(test_untranslatable);
    RUN(test_compatible_and_status);
    RUN(test_props_aliases);
    RUN(test_timer_irq);
    RUN(test_memreserve);
    free(buf);
    TEST_REPORT("test_fdt");
}
